export const SHARING_TASKS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Memecah pekerjaan",q:"Langkah pertama membagi tugas kelompok:",options:["Pecah pekerjaan besar menjadi bagian-bagian yang lebih kecil & jelas","Langsung tunjuk siapa mengerjakan apa tanpa tahu apa saja pekerjaannya","Kerjakan bersama-sama semua di satu bagian"],answer:0,explain:"Kamu tidak bisa membagi adil kalau belum tahu apa saja yang harus dikerjakan. Daftar dulu, baru bagi.",hint:"Pecah & daftar dulu, atau langsung tunjuk?"},
{n:2,type:"mcq",micro:"Pembagian yang adil",q:"Pembagian tugas terasa adil ketika...",options:["Yang paling vokal memilih bagian termudah dulu, sisanya mengambil yang tersisa","Beban tiap orang kira-kira sebanding, cocok dengan kekuatan, & semua kebagian","Yang paling rajin mendapat bagian berat karena dianggap mampu, yang lain bagian ringan"],answer:1,explain:"Adil bukan berarti persis sama, tapi sebanding & masuk akal untuk tiap orang.",hint:"Sebanding & cocok kekuatan, atau menumpuk ke satu orang?"},
{n:3,type:"mcq",micro:"Menghitung beban",q:"Untuk mengecek pembagian sudah seimbang, tim bisa...",options:["Lihat siapa yang mengeluh paling keras, lalu kurangi bagiannya tanpa memeriksa besar pekerjaannya","Anggap sudah adil karena semua mendapat bagian, tanpa memperkirakan lama mengerjakannya","Perkirakan bersama kira-kira berapa jam/tingkat kesulitan tiap bagian, lalu sesuaikan"],answer:2,explain:"Perkiraan kasar (jam/kesulitan) menangkap ketidakseimbangan yang tidak terlihat dari nama tugas.",hint:"Perkirakan beban lalu sesuaikan, atau lihat siapa mengeluh?"},
{n:4,type:"mcq",micro:"Berbagi alat/sumber daya",q:"Timmu punya satu laptop yang bagus & harus dipakai bergantian. Cara adil:",options:["Buat jadwal pemakaian bersama sesuai kebutuhan tiap bagian, prioritaskan yang paling butuh","Satu orang memakainya terus karena paling mahir, sementara yang lain bekerja tanpa laptop","Rebutan saja, siapa cepat dia dapat, karena itu cara paling sederhana dan tak perlu membuat jadwal"],answer:0,explain:"Sumber daya terbatas dibagi dengan jadwal & prioritas, bukan rebutan atau dominasi.",hint:"Jadwal + prioritas, atau satu orang / rebutan?"},
{n:5,type:"mcq",micro:"Berbagi informasi",q:"Kamu menemukan sumber/data yang sangat berguna untuk proyek. Sikap:",options:["Berikan hanya kepada satu teman dekat yang kamu percaya di tim","Bagikan ke seluruh tim di kanal bersama supaya semua bisa memakainya","Simpan sendiri agar bagianmu terlihat paling bagus di antara anggota"],answer:1,explain:"Menyimpan informasi berguna dari timmu sendiri merugikan hasil bersama.",hint:"Bagikan ke semua, atau simpan / pilih-pilih?"},
{n:6,type:"mcq",micro:"Tugas yang tidak ada yang mau",q:"Ada bagian membosankan yang tidak ada yang mau (mis. mengetik ulang data). Cara adil:",options:["Paksa anggota yang paling pendiam mengerjakannya sendirian, karena ia jarang memprotes","Biarkan tidak dikerjakan, karena bagian yang membosankan kurang penting untuk hasil akhir proyek","Bagi rata (tiap orang sebagian), atau gilir, atau tukar dengan keringanan di bagian lain"],answer:2,explain:"Tugas yang tidak menyenangkan dibagi rata atau dikompensasi, bukan ditimpakan ke satu orang.",hint:"Bagi rata / gilir / kompensasi, atau paksa yang pendiam?"},
{n:7,type:"mcq",micro:"Berbagi tugas sesuai kekuatan",q:"Membagi tugas berdasarkan kekuatan tiap orang berarti...",options:["Yang jago menggambar pegang desain, yang teliti pegang cek data — tapi tetap seimbangkan beban & beri ruang belajar","Yang paling mampu mengerjakan semua bagian supaya hasilnya paling bagus dan anggota lain tidak membuat kesalahan","Undi acak tanpa melihat kemampuan, supaya semua kebagian bagian yang keluar dan tidak merasa dibeda-bedakan"],answer:0,explain:"Mencocokkan tugas dengan kekuatan membuat kerja lebih cepat & baik; tapi jaga keseimbangan & kesempatan belajar.",hint:"Cocokkan kekuatan (+ seimbang + belajar), atau semua ke yang mampu / undi?"},
{n:8,type:"mcq",micro:"Tugas yang saling bergantung",q:"Bagian A harus selesai dulu sebelum B bisa mulai. Saat membagi tugas, ini berarti...",options:["Bagian B dikerjakan lebih dulu sebelum A, supaya waktu tidak terbuang dan hasil keduanya dicocokkan","Pemegang A punya tenggat lebih ketat; tim menyusun urutan & tenggat sesuai ketergantungan","Tidak berpengaruh pada pembagian tugas, karena tiap bagian bisa dikerjakan kapan saja"],answer:1,explain:"Tugas di awal rantai butuh tenggat lebih awal karena orang lain menunggunya.",hint:"A tenggatnya lebih ketat, atau tak berpengaruh?"},
{n:9,type:"order",micro:"Membagi tugas kelompok",q:"Urutkan langkah membagi tugas dengan adil.",items:["Daftar semua pekerjaan yang dibutuhkan","Perkirakan beban & ketergantungan tiap bagian","Cocokkan dengan kekuatan/minat, seimbangkan beban","Tuliskan: siapa - bagian apa - tenggat, minta tiap orang konfirmasi"],answer:[0,1,2,3],explain:"Daftar → perkirakan beban → cocokkan & seimbangkan → tulis & konfirmasi.",hint:"Apa yang didaftar sebelum membagi?"},
{n:10,type:"mcq",micro:"Berbagi ruang & waktu",q:"Tim mengerjakan proyek fisik (mis. maket) di ruang terbatas. Cara berbagi:",options:["Semua bekerja bersamaan berdesakan di ruang sempit tanpa jadwal giliran, supaya terasa kompak dan cepat selesai","Satu orang menguasai ruang dan alat selama dibutuhkan, sedangkan yang lain menunggu sampai ia selesai","Jadwalkan giliran/sesi kerja, bagi area, & rapikan setelah dipakai supaya yang berikutnya bisa langsung mulai"],answer:2,explain:"Berbagi ruang butuh jadwal, pembagian area, & etika 'tinggalkan bersih untuk yang berikutnya'.",hint:"Jadwal + bagi area + rapikan, atau berdesakan / dikuasai?"},
{n:11,type:"tf",micro:"Adil bukan berarti identik",q:"Benar atau Salah: Pembagian tugas yang adil tidak harus berarti tiap orang mengerjakan hal yang persis sama — yang penting bebannya sebanding & masuk akal untuk tiap orang.",answer:true,explain:"Satu orang bisa pegang desain (butuh keterampilan), satu pegang riset (butuh waktu). Berbeda jenis, sebanding beban.",hint:"Adil = identik, atau sebanding?"},
{n:12,type:"tf",micro:"Menyimpan sumber daya untuk diri sendiri",q:"Benar atau Salah: Dalam tim, wajar menyimpan sumber/data yang kamu temukan hanya untuk dirimu supaya bagianmu terlihat lebih unggul daripada anggota lain.",answer:false,explain:"Sebaliknya, itu adalah bersaing di dalam tim sendiri & merugikan hasil bersama. Berbagi sumber memperkuat semua & itulah tujuan tim.",hint:"Simpan sendiri demi unggul, atau bagikan demi hasil bersama?"},
{n:13,type:"mcq",micro:"Menawarkan bantuan",q:"Bagianmu selesai lebih dulu. Sikap yang baik:",options:["Tawarkan bantuan ke yang masih kesulitan: 'Punyaku udah, ada yang bisa kubantu?'","Duduk santai menonton teman yang masih kesulitan, karena bagianmu sudah beres","Menyombongkan diri karena bagianmu paling cepat selesai sambil mengejek teman yang lambat"],answer:0,explain:"Berbagi tugas juga berarti berbagi beban saat ada yang tertinggal — tim menang bersama.",hint:"Tawarkan bantuan, atau menonton / menyombong?"},
{n:14,type:"mcq",micro:"Meminta bantuan",q:"Bagianmu ternyata lebih berat dari perkiraan & kamu kewalahan. Sikap:",options:["Menyerahkan bagian itu diam-diam kepada teman lain tanpa bilang, berharap ia mengerjakannya","Minta bantuan tim lebih awal: 'Bagian ini ternyata besar, ada yang bisa ambil sebagian?'","Diam dan mengerjakan sendiri sampai terlambat, karena meminta bantuan dianggap tanda tidak mampu"],answer:1,explain:"Meminta bantuan lebih awal adalah bagian dari berbagi beban, bukan tanda lemah.",hint:"Minta bantuan lebih awal, atau diam sampai gagal?"},
{n:15,type:"mcq",micro:"Berbagi kredit",q:"Saat presentasi hasil tim, cara berbagi pengakuan yang adil:",options:["Presenter mengambil pujian karena dialah yang berdiri dan berbicara di depan","Hanya berkata 'ini hasil kami' tanpa menyebut siapa mengerjakan apa","Sebut kontribusi tiap anggota & sampaikan sebagai hasil bersama"],answer:2,explain:"Berbagi tugas juga berarti berbagi kredit. Mengakui kontribusi orang membuat mereka mau bekerja sama lagi.",hint:"Sebut kontribusi semua, atau ambil sendiri?"},
{n:16,type:"mcq",micro:"Alat pribadi untuk tim",q:"Kamu punya alat/aplikasi berbayar yang bisa membantu proyek. Sikap yang murah hati tapi wajar:",options:["Tawarkan memakainya untuk bagian tim yang butuh, dengan batas yang kamu nyaman; kamu tidak wajib, tapi berbagi memperkuat tim","Wajib menyerahkan semuanya tanpa batas kepada tim, termasuk akunmu, karena anggota tim berhak memakai milikmu kapan saja","Sembunyikan bahwa kamu punya aplikasi itu, supaya tak ada yang meminta dan kamu tidak perlu menjelaskan batasanmu"],answer:0,explain:"Berbagi sumber daya pribadi itu baik, dalam batas yang kamu ikhlas. Menyembunyikan yang bisa membantu tim kurang tepat.",hint:"Tawarkan dalam batas nyaman, atau serahkan semua / sembunyikan?"},
{n:17,type:"mcq",micro:"Tugas yang belum jelas milik siapa",q:"Ada pekerjaan yang penting tapi tidak masuk ke bagian siapa pun. Sikap tim:",options:["Semua menunggu orang lain melakukannya lebih dulu, karena belum ada yang merasa itu tugasnya","Bahas & tugaskan ke seseorang (atau bagi), jangan biarkan menggantung karena 'bukan bagianku'","Biarkan saja; mungkin nanti ada yang mengerjakan tanpa disuruh, dan kalau tidak, berarti kurang penting"],answer:1,explain:"Tugas 'yatim' (tanpa pemilik) sering jadi bagian yang gagal. Tugaskan secara sadar.",hint:"Tugaskan secara sadar, atau biarkan menggantung?"},
{n:18,type:"mcq",micro:"Berbagi tugas & tanggung jawab",q:"Setelah bagianmu diberikan, tanggung jawabmu adalah...",options:["Mengerjakannya hanya kalau diingatkan oleh ketua, karena tanggung jawab baru muncul ketika ada yang menagih hasil pekerjaannya","Menyerahkan hasil seadanya yang penting selesai tepat waktu, tanpa memeriksa apakah sudah sesuai dengan standar yang disepakati tim","Menyelesaikannya sesuai standar & tenggat, & mengabari tim bila ada risiko molor — bukan menunggu diingatkan terus"],answer:2,explain:"Berbagi tugas datang dengan berbagi tanggung jawab: kamu memegang bagian itu, jadi kamu yang memastikannya.",hint:"Selesaikan + kabari kendala, atau tunggu diingatkan?"},
{n:19,type:"mcq",micro:"Sumber daya waktu",q:"Anggota punya waktu luang berbeda-beda (ada yang sibuk ekskul). Cara adil membagi:",options:["Sesuaikan besar bagian dengan ketersediaan waktu tiap orang, bukan memberi beban sama ke yang punya waktu sangat sedikit","Semua bagian dibuat persis sama besar, berapa pun kesibukan tiap anggota, karena itu cara paling adil bagi tim","Yang sibuk dibebaskan dari tugas, sedangkan yang lain mengerjakan semuanya tanpa penyesuaian di kemudian hari"],answer:0,explain:"Adil mempertimbangkan realitas: yang punya lebih sedikit waktu pegang bagian lebih kecil (tapi tetap kebagian).",hint:"Sesuaikan dengan ketersediaan, atau sama rata / bebas total?"},
{n:20,type:"open",micro:"Membagi tugas untuk sebuah proyek",q:"Tim 4 orang membuat presentasi + laporan tertulis tentang sejarah sekolah. Anggota: Ana (jago desain, waktu sedikit karena ekskul), Budi (teliti, banyak waktu), Cici (jago menulis), Deni (jago wawancara & bicara). Rancang pembagian tugas yang adil & memakai kekuatan, lalu jelaskan cara kamu memastikan bebannya seimbang.",explain:"Jawaban baik mencocokkan tugas dengan kekuatan tiap orang (Deni wawancara+presenter, Budi riset+cek+format, Cici menulis, Ana desain) DAN menyeimbangkan beban dengan ketersediaan waktu (Ana bagian terbatas karena sibuk, Budi bagian terberat karena banyak waktu), lalu menyebut cara mengecek keseimbangan (perkiraan jam, geser tugas, tenggat bertahap).",hint:"Cocokkan tugas dengan kekuatan; sesuaikan besar bagian dengan waktu tiap orang; lalu cek keseimbangan (perkiraan jam, tenggat bertahap).",sample:"Pembagian: Deni - mewawancarai narasumber (guru senior, alumni, penjaga sekolah), mengumpulkan cerita & foto lama, dan menjadi presenter utama. Budi - meneliti dokumen & arsip, menyusun kronologi/timeline, mengecek fakta & tanggal, dan merapikan format laporan (karena teliti & punya banyak waktu, ia pegang bagian yang butuh ketekunan & jam kerja lebih). Cici - menulis naskah laporan tertulis berdasarkan bahan dari Deni & Budi, dan menulis narasi/poin untuk slide. Ana - membuat desain slide & tata letak laporan (butuh keterampilan tapi bisa dikerjakan dalam waktu lebih terbatas), plus memilih & mengedit foto. Aku (koordinator) - menyusun jadwal, menggabungkan, dan membantu bagian yang tertinggal. Memastikan seimbang: karena Ana waktunya sedikit, bagiannya lebih fokus & terbatas (desain saja, tidak ikut riset); Budi yang punya banyak waktu memegang bagian paling memakan jam (riset arsip + cek fakta + format). Setelah membagi, kami perkirakan bersama berapa jam kira-kira tiap bagian dan geser tugas kecil bila ada yang jelas kelebihan. Kami juga susun tenggat bertahap: wawancara & riset dulu (minggu 1), penulisan (minggu 2), desain & penggabungan (minggu 3), supaya kerja tidak menumpuk di satu orang pada saat yang sama."},
{n:21,type:"classify",micro:"Berbagi vs menimbun",q:"Kelompokkan tiap perilaku ke 'Berbagi (menguatkan tim)' atau 'Menimbun (melemahkan tim)'.",items:["Membagikan referensi bagus ke kanal tim","Menyimpan trik/template sendiri agar bagianku terlihat lebih hebat","Menawarkan bantuan ke anggota yang kewalahan","Memakai satu-satunya alat bagus terus tanpa gilir"],groups:["Berbagi (menguatkan tim)","Menimbun (melemahkan tim)"],answer:{"Berbagi (menguatkan tim)":["Membagikan referensi bagus ke kanal tim","Menawarkan bantuan ke anggota yang kewalahan"],"Menimbun (melemahkan tim)":["Menyimpan trik/template sendiri agar bagianku terlihat lebih hebat","Memakai satu-satunya alat bagus terus tanpa gilir"]},explain:"Berbagi: info, bantuan, & sumber daya mengalir ke seluruh tim. Menimbun: menahannya demi keunggulan pribadi.",hint:"Mengalir ke tim, atau ditahan untuk diri sendiri?"},
{n:22,type:"mcq",micro:"Beban tersembunyi",q:"Sebuah bagian bisa terlihat kecil di nama ('bikin poster') tapi sebenarnya berat. Cara menangkapnya saat membagi:",options:["Biarkan yang mengerjakan mengeluh nanti kalau berat, lalu tim membahas apakah perlu dibantu","Bahas isi tiap bagian secara detail & perkirakan bersama waktunya, bukan hanya menyebut judulnya","Percaya pada nama bagiannya, karena judul sudah cukup menggambarkan besar dan lamanya pekerjaan"],answer:1,explain:"Membagi berdasarkan judul saja sering menghasilkan ketidakadilan tersembunyi. Bahas isinya.",hint:"Bahas isi & perkirakan waktu, atau percaya judul?"},
{n:23,type:"mcq",micro:"Menukar bagian",q:"Setelah pembagian, seorang anggota merasa bagiannya tidak cocok & ingin menukar dengan anggota lain yang setuju. Sikap tim:",options:["Dilarang, karena pembagian awal bersifat mutlak dan tidak boleh diubah sedikit pun","Ditukar diam-diam tanpa memberi tahu tim, supaya prosesnya terasa lebih cepat","Boleh, selama keduanya setuju & beban tetap seimbang; catat perubahannya"],answer:2,explain:"Pertukaran yang disepakati & tercatat itu sehat. Yang bermasalah adalah pertukaran diam-diam.",hint:"Boleh bila keduanya setuju & tercatat, atau dilarang / diam-diam?"},
{n:24,type:"mcq",micro:"Berbagi & belajar",q:"Ketika anggota yang lebih ahli berbagi caranya (bukan hanya hasilnya) dengan yang kurang ahli:",options:["Seluruh tim jadi lebih kuat — lebih banyak orang bisa mengerjakan hal itu di masa depan","Membuang waktu, karena lebih baik anggota yang ahli mengerjakan semuanya sendiri supaya cepat","Membuat yang ahli kehilangan keunggulannya, sehingga ia tidak lagi dianggap spesial di tim"],answer:0,explain:"Berbagi keterampilan (bukan hanya menyerahkan hasil) menyebarkan kemampuan & mengurangi ketergantungan pada satu orang.",hint:"Tim jadi lebih kuat, atau buang waktu?"},
{n:25,type:"mcq",micro:"Sumber daya bersama vs pribadi",q:"Dokumen kerja tim sebaiknya...",options:["Disebar ke banyak tempat berbeda (tiap orang punya folder sendiri), supaya bila satu hilang masih ada salinan","Disimpan di tempat bersama yang semua bisa akses & edit (dengan aturan penamaan), bukan di laptop satu orang","Disimpan di laptop koordinator saja, supaya satu orang yang mengurus dan anggota lain tidak mengacaukan isinya"],answer:1,explain:"Dokumen di satu laptop = tim macet kalau orang itu tidak ada. Tempat bersama menjaga semua bisa lanjut.",hint:"Tempat bersama yang bisa diakses semua, atau satu laptop / tersebar?"},
{n:26,type:"mcq",micro:"Membagi tugas & tanggung jawab hasil",q:"Kalau bagianmu selesai bagus tapi bagian lain buruk & hasil tim jelek, sikap:",options:["'Aku sudah mengerjakan bagianku dengan baik, jadi sisanya bukan urusanku & aku tidak perlu ikut memikirkannya lagi,' katamu kepada tim","Menyalahkan anggota yang bagiannya buruk di depan guru, supaya terlihat jelas bahwa bagianmu sudah benar & nilaimu tidak ikut turun","Ikut membantu memperbaiki & merefleksikan bagaimana tim bisa saling mendukung lebih baik — bukan 'itu bukan salahku'"],answer:2,explain:"Berbagi tugas datang dengan tanggung jawab bersama atas hasil keseluruhan.",hint:"Bantu perbaiki + refleksi, atau 'bukan salahku' / menyalahkan?"},
{n:27,type:"tf",micro:"Menyeimbangkan beban itu proses",q:"Benar atau Salah: Menyeimbangkan beban tugas paling baik diserahkan pada kebetulan & pada 'yang rela mengerjakan lebih', bukan dibahas secara sengaja.",answer:false,explain:"Sebaliknya, membiarkan beban jatuh pada 'yang rela' menghasilkan kelelahan & kekesalan yang menumpuk. Keseimbangan sebaiknya dibahas & dicek bersama secara sengaja.",hint:"Dicek bersama secara sengaja, atau diserahkan pada kebetulan?"},
{n:28,type:"tf",micro:"Tugas 'yatim' tidak masalah?",q:"Benar atau Salah: Pekerjaan penting yang tidak masuk ke bagian siapa pun bisa dibiarkan begitu saja, karena biasanya akan ada anggota yang berinisiatif mengerjakannya sendiri.",answer:false,explain:"Sebaliknya, tugas tanpa pemilik yang jelas sering menjadi bagian yang gagal karena setiap orang mengira orang lain akan mengerjakannya. Tugaskan secara sadar.",hint:"Biarkan menggantung, atau tugaskan secara sadar?"},
{n:29,type:"mcq",micro:"Berbagi tugas di tim yang timpang kemampuan",q:"Tim berisi anggota yang kemampuannya sangat berbeda. Cara membagi yang adil & mengembangkan:",options:["Yang lebih ahli pegang bagian inti + membimbing; yang kurang ahli pegang bagian pendukung yang jelas + belajar dari yang ahli","Yang ahli mengerjakan semuanya sendiri sedangkan yang kurang ahli hanya menonton, supaya hasilnya bagus dan bebas kesalahan pemula","Semua bagian dibagi sama persis tanpa peduli kemampuan, sehingga yang kurang ahli kewalahan dan yang ahli menunggu"],answer:0,explain:"Berbagi tugas di tim timpang berarti menyeimbangkan hasil (yang ahli di bagian sulit) & perkembangan (yang lain belajar sambil berkontribusi nyata).",hint:"Ahli inti + bimbing, kurang ahli pendukung + belajar — atau ahli semua / sama rata buta?"},
{n:30,type:"order",micro:"Menyeimbangkan ulang beban di tengah proyek",q:"Urutkan langkah menyeimbangkan ulang tugas ketika ternyata satu orang kewalahan.",items:["Kenali gejalanya: bagian itu tersendat, orangnya kelihatan stres/minta bantuan","Pahami kenapa: bagiannya lebih besar dari perkiraan, atau ada kendala pribadi","Cari kapasitas: siapa yang bagiannya sudah ringan/selesai & bisa membantu","Pindahkan sebagian tugas, sesuaikan tenggat, perbarui catatan"],answer:[0,1,2,3],explain:"Kenali → pahami → cari kapasitas → pindahkan & catat. Menyeimbangkan ulang adalah tanda tim yang responsif.",hint:"Apa yang dikenali sebelum memindahkan tugas?"},
{n:31,type:"mcq",micro:"Berbagi & rasa memiliki",q:"Meski tugas dibagi, tiap anggota sebaiknya tetap merasa...",options:["Bahwa proyek itu milik koordinator saja","Ikut memiliki keseluruhan proyek, bukan hanya kotak tugasnya sendiri","Hanya bertanggung jawab pada bagiannya & tidak peduli sisanya"],answer:1,explain:"Berbagi tugas tidak boleh menghapus rasa memiliki bersama. 'Ini proyek kita' menjaga semua peduli pada hasil akhir.",hint:"Ikut memiliki keseluruhan, atau hanya kotak sendiri?"},
{n:32,type:"tf",micro:"Berbagi sumber = tim lebih kuat",q:"Benar atau Salah: Tim di mana tiap anggota menyimpan referensi, alat, dan keterampilannya sendiri biasanya lebih cepat daripada tim yang berbagi secara terbuka.",answer:false,explain:"Sebaliknya, sumber yang dibagikan dipakai berkali-kali oleh banyak orang & mengurangi usaha yang diulang. Yang disimpan hanya menguntungkan satu orang.",hint:"Berbagi = tim lebih kuat, atau menyimpan lebih menguntungkan?"},
{n:33,type:"mcq",micro:"Membagi tugas presentasi",q:"Untuk presentasi kelompok, membagi 'siapa bicara bagian mana' sebaiknya...",options:["Satu orang berbicara untuk seluruh kelompok dari awal sampai akhir, sedangkan yang lain berdiri diam di panggung tanpa bicara","Diacak di tempat saat presentasi berlangsung, supaya terasa spontan, walau anggota belum tentu menguasai bagiannya","Sesuai bagian yang mereka kerjakan/kuasai, dengan porsi waktu bicara yang kira-kira sebanding, & transisi yang disepakati"],answer:2,explain:"Berbagi 'waktu tampil' juga bagian dari pembagian adil; tiap orang mendapat kesempatan & tanggung jawab.",hint:"Sesuai bagian + porsi sebanding + transisi, atau satu orang / acak?"},
{n:34,type:"mcq",micro:"Berbagi tanggung jawab menggabungkan",q:"Menggabungkan semua bagian jadi satu hasil utuh adalah tugas yang...",options:["Perlu ditugaskan ke seseorang (atau dilakukan bersama) & dihitung sebagai beban — bukan diasumsikan 'nanti kelar sendiri'","Terjadi dengan sendirinya sehingga tidak perlu dijadwalkan, dihitung, ataupun ditugaskan kepada anggota tim tertentu","Bukan pekerjaan nyata, sehingga tidak perlu dihitung sebagai beban dan boleh dikerjakan kalau sempat saja"],answer:0,explain:"Penggabungan (format seragam, transisi, cek konsistensi) sering memakan waktu & harus masuk hitungan pembagian.",hint:"Ditugaskan & dihitung, atau otomatis?"},
{n:35,type:"mcq",micro:"Berbagi saat sumber daya sangat terbatas",q:"Tim hanya punya waktu 1 jam bersama & 1 komputer. Cara memaksimalkan:",options:["Satu orang memakai komputer sepanjang sesi, sedangkan yang lain menganggur menunggu giliran sampai waktu habis","Rencanakan sebelum sesi: siapa mengerjakan apa di komputer & urutannya; yang menunggu mengerjakan bagian non-komputer","Semua berdesakan di depan komputer sekaligus tanpa pembagian pekerjaan, sehingga sulit mengetik atau melihat layar"],answer:1,explain:"Perencanaan pemakaian sumber daya terbatas sebelum sesi membuat setiap menit terpakai.",hint:"Rencanakan giliran + kerja paralel, atau berdesakan / menganggur?"},
{n:36,type:"mcq",micro:"Menolak menanggung beban tidak adil",q:"Kamu terus-menerus diminta 'menutupi' bagian orang lain. Sikap sehat:",options:["Terus menanggung bagian orang lain sambil menyimpan kesal & tidak mengatakan apa-apa, berharap suatu saat ia sadar dengan sendirinya","Berhenti mengerjakan bagianmu sebagai bentuk protes kepada tim, supaya semuanya sadar bahwa kamu sudah terlalu lelah menutupi","Bantu sesekali bila darurat, tapi sampaikan dengan jelas bahwa pola ini tidak adil & tim perlu membagi ulang atau anggota itu perlu menjalankan bagiannya"],answer:2,explain:"Berbagi beban punya batas. Menanggung terus-menerus tanpa bilang menghasilkan kelelahan & merusak tim.",hint:"Bantu sesekali + suarakan pola tidak adil, atau tanggung terus / mogok?"},
{n:37,type:"tf",micro:"Berbagi tugas butuh koordinasi",q:"Benar atau Salah: Membagi tugas dengan jelas tidak menghilangkan kebutuhan tim untuk terus berkomunikasi & berkoordinasi selama proyek berjalan.",answer:true,explain:"Bagian-bagian harus nyambung. Update rutin memastikan tidak ada yang menyimpang atau menemukan kejutan di akhir.",hint:"Tetap butuh koordinasi, atau cukup masing-masing kerjakan?"},
{n:38,type:"mcq",micro:"Berbagi tugas & tenggat bertahap",q:"Menyusun tenggat internal bertahap (bagian A minggu 1, B minggu 2) membantu karena...",options:["Pekerjaan tidak menumpuk di satu orang pada waktu bersamaan, & bagian yang saling bergantung punya urutan","Membuat proyek berjalan lebih lama karena setiap bagian harus menunggu bagian lain sebelum dimulai","Tidak ada manfaatnya, karena pekerjaan akan selesai pada waktunya tanpa perlu dijadwalkan dulu"],answer:0,explain:"Tenggat bertahap meratakan beban sepanjang waktu & menghormati ketergantungan antar bagian.",hint:"Meratakan beban & mengatur urutan, atau memperlama?"},
{n:39,type:"mcq",micro:"Berbagi & transparansi",q:"Agar pembagian tugas terasa adil bagi semua, prosesnya sebaiknya...",options:["Rahasia: tiap orang hanya diberi tahu bagiannya sendiri dan tidak melihat daftar milik anggota lain","Terbuka: semua melihat daftar pekerjaan, ikut menimbang beban, & tahu siapa dapat apa & kenapa","Diputuskan koordinator sendirian di belakang layar, lalu anggota menerima hasilnya tanpa bisa bertanya"],answer:1,explain:"Keadilan yang dirasakan datang dari proses yang transparan, bukan hanya hasil yang kebetulan adil.",hint:"Proses terbuka, atau diputuskan diam-diam?"},
{n:40,type:"open",micro:"Menyeimbangkan pembagian yang timpang",q:"Setelah seminggu, timmu sadar: Rani mengerjakan 3 bagian besar, Dito 1 bagian kecil, dan dua anggota lain masing-masing 1 bagian sedang. Rani mulai kewalahan dan kesal. Rancang bagaimana tim menyeimbangkan ulang secara adil, minimal 4 langkah.",explain:"Jawaban baik: bahas terbuka sebelum Rani meledak, perkirakan beban tiap bagian secara objektif, pindahkan bagian dari Rani ke yang paling ringan (Dito) atau pecah & sebar ke beberapa orang, sesuaikan tenggat, perbarui catatan + konfirmasi, dan akui ketidakadilan awal + jadikan pelajaran.",hint:"Bahas terbuka → perkirakan beban objektif → pindahkan dari yang berat ke yang ringan / pecah & sebar → sesuaikan tenggat → perbarui catatan → akui & jadikan pelajaran.",sample:"(1) Bahas terbuka di rapat, bukan menunggu Rani meledak: 'Kayaknya pembagian kita agak timpang. Yuk kita lihat lagi bareng.' (2) Buat daftar semua bagian dan perkirakan bersama beban tiap bagian (jam/kesulitan) — ini akan menunjukkan seberapa besar ketimpangannya secara objektif, bukan sekadar perasaan. (3) Lihat apa yang sudah Rani kerjakan dan apa yang tersisa dari 3 bagiannya; ambil satu bagian yang belum ia mulai (atau bagian yang bisa dipecah) dan pindahkan ke Dito, yang bebannya paling ringan. (4) Kalau Dito tidak sanggup atau bagiannya butuh keterampilan tertentu, bagi bagian itu jadi potongan kecil dan sebar ke Dito + dua anggota sedang, masing-masing ambil sedikit. (5) Sesuaikan tenggat bila perlu, karena orang yang baru mengambil bagian butuh waktu. (6) Perbarui catatan pembagian dan minta semua konfirmasi versi baru. (7) Akui ke Rani bahwa pembagian awal kurang adil dan berterima kasih ia sudah menahan sejauh ini; jadikan pelajaran untuk mengecek keseimbangan beban sejak awal di proyek berikutnya."},
{n:41,type:"mcq",micro:"Skenario: anggota selalu ambil bagian termudah",q:"Seorang anggota selalu cepat 'memesan' bagian termudah sebelum yang lain sempat bicara. Sikap tim:",options:["Biarkan saja, dia memang lincah & cepat mengambil kesempatan, jadi wajar kalau ia mendapat bagian yang paling mudah di tim ini","Semua ikut berebut lebih cepat memesan bagian yang mudah, supaya tidak tertinggal dan mendapat bagian berat sendirian","Buat proses pembagian yang lebih adil: daftar semua bagian dulu, timbang bebannya, baru bagi bersama — bukan siapa cepat dia dapat"],answer:2,explain:"'Siapa cepat dia dapat' menghasilkan ketidakadilan. Proses terstruktur (daftar → timbang → bagi bersama) lebih adil.",hint:"Proses terstruktur bersama, atau siapa cepat / ikut rebutan?"},
{n:42,type:"mcq",micro:"Skenario: berbagi file & versi",q:"Tim mengerjakan satu dokumen bersama & sering terjadi 'file-nya ketimpa' atau 'ini versi yang mana?'. Solusi:",options:["Sepakati satu lokasi & satu file utama, aturan penamaan versi, & siapa yang boleh menggabungkan perubahan","Tiap orang menyimpan versinya sendiri di laptop masing-masing, lalu digabung manual di menit terakhir oleh yang sempat","Kirim file bolak-balik lewat chat tanpa aturan penamaan dan lokasi utama, lalu anggap versi terakhir yang paling benar"],answer:0,explain:"Berbagi dokumen butuh aturan: satu sumber kebenaran, penamaan versi, & proses penggabungan.",hint:"Satu file utama + aturan versi, atau tiap orang simpan sendiri?"},
{n:43,type:"mcq",micro:"Skenario: satu anggota tidak punya akses",q:"Seorang anggota tidak punya internet di rumah, jadi sulit ikut mengerjakan bagian yang butuh riset online. Sikap tim yang adil:",options:["Kecualikan dia dari tim sepenuhnya, karena tanpa internet ia tidak mungkin berkontribusi, & anggota lain bisa bekerja lebih cepat tanpa dia","Sesuaikan: beri dia bagian yang bisa dikerjakan offline (menulis, menyusun, menghitung), atau atur waktu bersama di sekolah/perpustakaan untuk bagian online-nya","Tetap beri dia bagian riset online seperti anggota lain, lalu salahkan dia di depan guru kalau ternyata bagiannya tidak selesai tepat waktu"],answer:1,explain:"Pembagian adil mempertimbangkan akses & sumber daya nyata tiap anggota, bukan mengasumsikan semua sama.",hint:"Sesuaikan dengan akses / atur waktu bersama, atau paksakan / kecualikan?"},
{n:44,type:"mcq",micro:"Skenario: berbagi alat mahal",q:"Kamu punya kamera bagus yang dibutuhkan untuk proyek video tim. Sikap:",options:["Wajib menyerahkan kameramu kepada anggota yang membutuhkannya tanpa syarat, karena kamu bagian dari tim dan milik tim dipakai bersama","Sembunyikan bahwa kamu punya kamera bagus, supaya tidak diminta dan tidak perlu menjelaskan alasan atau batasanmu kepada anggota lain yang bertanya","Tawarkan meminjamkannya untuk syuting bersama (kamu ikut menjaga), atau kamu jadi juru kamera; kamu tidak wajib menyerahkannya tanpa pengawasan"],answer:2,explain:"Berbagi sumber daya pribadi yang berharga wajar dilakukan dengan cara yang kamu nyaman (mis. kamu ikut mengoperasikannya), bukan tanpa batas atau tidak sama sekali.",hint:"Tawarkan dengan cara yang kamu nyaman, atau serahkan tanpa syarat / sembunyikan?"},
{n:45,type:"order",micro:"Membagi tugas + menetapkan tenggat bertahap",q:"Urutkan langkah membagi tugas proyek 3 minggu dengan tenggat bertahap.",items:["Daftar pekerjaan & tentukan mana yang harus selesai lebih dulu (yang lain bergantung padanya)","Bagi ke anggota sesuai kekuatan & ketersediaan waktu, seimbangkan beban","Tetapkan tenggat internal per bagian sesuai urutan ketergantungan, dengan bantalan sebelum tenggat asli","Sepakati waktu cek kemajuan di antara tenggat-tenggat itu"],answer:[0,1,2,3],explain:"Daftar & urutan ketergantungan → bagi & seimbangkan → tenggat bertahap → cek kemajuan. Beban jadi merata sepanjang waktu.",hint:"Apa yang ditentukan sebelum menetapkan tenggat bertahap?"},
{n:46,type:"mcq",micro:"Skenario: kamu punya lebih banyak waktu",q:"Kamu satu-satunya anggota yang tidak sibuk kegiatan lain minggu ini. Sikap tim yang adil:",options:["Wajar bila kamu mengambil bagian sedikit lebih besar minggu ini; tim bisa menyeimbangkan dengan anggota lain mengambil lebih di minggu mereka lebih luang","Semua bagian tetap dibuat sama besar berapa pun kesibukan tiap anggota, karena itulah arti keadilan sebenarnya, dan tidak boleh ada tawar-menawar","Kamu mengerjakan semuanya sendirian setiap minggu karena kamu luang, sedangkan anggota lain tidak perlu menyumbang lagi, dan itu dianggap adil bagi tim"],answer:0,explain:"Keadilan bisa diseimbangkan sepanjang waktu, bukan hanya per minggu. Yang luang mengambil lebih sekarang, yang lain mengejar nanti.",hint:"Ambil sedikit lebih + seimbangkan lintas waktu, atau sama rata / semua kamu?"},
{n:47,type:"mcq",micro:"Skenario: berbagi tugas presentasi dengan anggota gugup",q:"Seorang anggota sangat gugup bicara di depan. Cara berbagi bagian presentasi yang adil & mendukung:",options:["Bebaskan dia dari semua bagian presentasi, lalu anggota lain menanggung seluruh pekerjaannya tanpa tugas pengganti, dan hal itu tidak perlu dibahas bersama tim","Beri dia bagian bicara yang lebih pendek/mudah dulu (dengan latihan bersama), atau peran pendukung seperti mengganti slide — tetap berkontribusi tanpa dipaksa","Paksa dia berbicara pada bagian terpanjang untuk 'melatih mental', walaupun belum berlatih dan sangat gugup, dan keberatannya tidak perlu dibahas bersama tim"],answer:1,explain:"Berbagi adil menyesuaikan dengan kemampuan sambil tetap melibatkan; bukan memaksa atau mengecualikan sepenuhnya.",hint:"Bagian lebih ringan + latihan / peran pendukung, atau paksa / bebaskan total?"},
{n:48,type:"mcq",micro:"Skenario: berbagi hasil kerja untuk dicek",q:"Sebelum digabung, tiap anggota sebaiknya...",options:["Menyimpan bagiannya sampai detik terakhir sebelum tenggat agar terlihat sempurna, tanpa memberi waktu bagi tim mengecek","Tidak membagikan apa-apa sampai proyek benar-benar selesai dan dikumpulkan, supaya hasil kerjanya tidak ditiru atau diubah","Membagikan bagiannya lebih awal ke tim untuk dicek, bukan menyerahkannya di menit terakhir tanpa waktu perbaikan"],answer:2,explain:"Berbagi hasil lebih awal memberi tim waktu memberi umpan balik & memperbaiki. Menyerahkan di akhir menghilangkan itu.",hint:"Bagikan lebih awal untuk dicek, atau tahan sampai akhir?"},
{n:49,type:"mcq",micro:"Skenario: anggota enggan berbagi caranya",q:"Anggota yang jago desain enggan mengajari yang lain 'biar dia yang selalu dibutuhkan'. Ini...",options:["Merugikan tim: membuat tim bergantung pada satu orang & yang lain tidak berkembang; berbagi keterampilan memperkuat tim","Wajar, itu keunggulannya, dan tim sebaiknya terus memanfaatkan dia sebagai ahli tunggal di bidang itu selama proyek","Bagus untuk tim, karena ahli yang menyimpan keterampilannya membuat hasil tim terlihat lebih unggul dari kelompok lain"],answer:0,explain:"Menahan pengetahuan demi 'menjadi tak tergantikan' membuat tim rapuh. Tim yang sehat menyebarkan kemampuan.",hint:"Merugikan (tim rapuh), atau wajar / bagus?"},
{n:50,type:"open",micro:"Skenario menyeluruh",q:"Kamu ketua tim 5 orang untuk pameran karya sekolah, waktu 4 minggu. Sumber daya terbatas: 1 ruang kerja yang bisa dipakai 2 jam/hari setelah sekolah, 2 laptop, dan anggaran kecil. Anggota punya jadwal & kemampuan berbeda. Rancang bagaimana kamu membagi tugas & sumber daya secara adil dan efisien. Minimal 6 keputusan konkret dengan alasan.",explain:"Jawaban baik memuat minimal 6 keputusan konkret dengan alasan: daftar pekerjaan + perkirakan beban, bagi sesuai kekuatan + ketersediaan + seimbangkan, jadwal pemakaian ruang bergilir sesuai prioritas, pembagian & aturan pemakaian laptop + file bersama, pengelolaan anggaran transparan, tenggat bertahap + cek kemajuan, berbagi hasil lebih awal untuk dicek, kepemimpinan menyeimbangkan + mengakui kontribusi.",hint:"Bagi TUGAS (daftar+perkirakan beban, cocokkan kekuatan+waktu, seimbangkan) & bagi SUMBER DAYA (jadwal ruang bergilir, aturan laptop+file, anggaran transparan), lalu tenggat bertahap + cek + berbagi hasil awal.",sample:"(1) Pertemuan pertama: daftar semua pekerjaan pameran (konsep & tema, pembuatan karya/materi, dekorasi ruang, publikasi, dokumentasi, penjaga stan saat hari-H), lalu perkirakan bersama beban tiap bagian. Alasan: tidak bisa membagi adil tanpa tahu isinya. (2) Tanyakan jadwal & kemampuan tiap anggota, bagi tugas sesuai kekuatan + ketersediaan waktu (yang sibuk pegang bagian lebih kecil/fleksibel, yang luang pegang bagian berat), seimbangkan beban dengan geser tugas kecil. Alasan: adil = sebanding, bukan identik. (3) Buat jadwal pemakaian ruang kerja: bagi 2 jam/hari ke pasangan/kelompok kecil sesuai bagian yang paling butuh ruang minggu itu (mis. minggu 1-2 untuk pembuat karya, minggu 3 untuk dekorasi); yang tidak di ruang mengerjakan bagian yang bisa di rumah. Alasan: sumber daya terbatas dipakai bergilir sesuai prioritas. (4) Bagi 2 laptop: satu untuk desain/publikasi, satu untuk dokumen & anggaran; sepakati jadwal & tempat penyimpanan file bersama + aturan penamaan versi. Alasan: mencegah 'file ketimpa' & rebutan. (5) Anggaran kecil: buat daftar kebutuhan bersama, prioritaskan yang wajib, catat tiap pengeluaran secara transparan, satu orang pegang uang & bon. Alasan: transparansi mencegah konflik uang. (6) Tenggat bertahap: konsep (minggu 1), pembuatan karya & materi (minggu 2-3), dekorasi & publikasi (minggu 3-4), gladi (akhir minggu 4). Cek kemajuan 2x seminggu. Alasan: beban merata & bagian yang bergantung punya urutan. (7) Semua bagikan hasilnya lebih awal untuk dicek bersama, bukan di menit terakhir. (8) Sebagai ketua, aku menggabungkan, membantu bagian yang tertinggal, & menjaga pembagian tetap seimbang; kontribusi tiap orang diakui saat pameran."},
{n:51,type:"mcq",micro:"Skenario: bagian selesai berbeda-beda waktu",q:"Anggota yang bagiannya selesai lebih dulu, sebaiknya...",options:["Menyuruh anggota yang lambat agar bekerja lebih cepat & memarahinya karena belum selesai, sambil dirinya sendiri bersantai di pinggir","Menawarkan diri mengambil tugas tambahan atau membantu yang tertinggal — bukan menganggap tugasnya sudah 'habis'","Berhenti berkontribusi karena bagiannya sendiri sudah selesai dengan baik, & sisanya dianggap menjadi urusan anggota yang masih tertinggal"],answer:1,explain:"Berbagi beban sepanjang proyek: yang selesai duluan membantu menyeimbangkan, bukan berhenti.",hint:"Bantu / ambil tugas tambahan, atau berhenti / menyuruh?"},
{n:52,type:"tf",micro:"Berbagi hasil lebih awal",q:"Benar atau Salah: Menahan bagianmu sampai persis di tenggat (agar 'sempurna') umumnya menghasilkan proyek akhir yang lebih baik daripada membagikannya beberapa hari lebih awal untuk dicek.",answer:false,explain:"Sebaliknya, membagikan lebih awal memberi waktu umpan balik & penyesuaian antar bagian, sehingga hasilnya lebih nyambung & rapi.",hint:"Bagikan lebih awal, atau di tenggat?"},
{n:53,type:"mcq",micro:"Skenario: sumber daya diberi tidak merata oleh guru",q:"Guru memberi kelompokmu sedikit lebih banyak bahan daripada kelompok lain. Sikap:",options:["Habiskan semua bahan meskipun tidak perlu, supaya tidak terbuang dan tim terlihat memanfaatkan pemberian guru","Sembunyikan kelebihan bahan dari kelompok lain agar mereka tidak meminta, karena guru memberikannya untuk kelompokmu","Pakai secukupnya untuk kebutuhan tim; kalau berlebih banyak, tawarkan ke kelompok lain yang kekurangan"],answer:2,explain:"Berbagi sumber daya juga berlaku antar kelompok: kelebihan yang tidak dipakai lebih baik dibagi daripada disia-siakan.",hint:"Pakai secukupnya + tawarkan kelebihan, atau habiskan / sembunyikan?"},
{n:54,type:"mcq",micro:"Skenario: menghitung kontribusi untuk penilaian",q:"Guru meminta pembagian tugas tim dilampirkan. Cara yang jujur & adil:",options:["Tuliskan apa yang benar-benar dikerjakan tiap orang secara jujur, termasuk bila ada perbedaan besar kontribusi","Tulis bahwa semua anggota mengerjakan sama rata walaupun kenyataannya berbeda, supaya suasana tim tetap damai","Sembunyikan siapa yang tidak berkontribusi demi solidaritas pada teman, sehingga guru mengira kerja tim sama baiknya"],answer:0,explain:"Kejujuran soal pembagian & kontribusi membantu penilaian adil, terutama bila ada penumpang gelap.",hint:"Jujur soal kontribusi nyata, atau samakan semua / sembunyikan?"},
{n:55,type:"mcq",micro:"Skenario: dua anggota mau bagian yang sama",q:"Dua anggota sama-sama ingin bagian favorit (mis. desain). Cara adil:",options:["Undi tanpa diskusi, lalu yang kalah harus menerima hasilnya walaupun kecewa dan pengalamannya tidak dipertimbangkan","Bagi (satu utama, satu asisten yang belajar), gilir per sub-bagian, atau diskusikan berdasarkan pengalaman & ketersediaan","Berikan kepada yang paling ngotot memintanya, karena berarti dia yang paling menginginkan bagian favorit itu"],answer:1,explain:"Konflik atas bagian favorit diselesaikan dengan pembagian, rotasi, atau kriteria — bukan siapa keras atau undi buta.",hint:"Bagi / gilir / kriteria, atau kasih yang ngotot / undi buta?"},
{n:56,type:"mcq",micro:"Skenario: berbagi tugas dadakan di hari-H",q:"Saat hari pameran/acara, muncul tugas dadakan (ada yang tumpah, tamu banyak). Sikap tim:",options:["'Itu bukan bagianku' lalu membiarkannya terjadi, karena tugas sudah dibagi sejak awal dan anggota tak wajib mengerjakan hal di luar perannya","Menunggu rapat berikutnya untuk memutuskan siapa yang menanganinya, walaupun tamu sudah banyak dan masalah makin membesar","Fleksibel: siapa yang terdekat/terluang menanganinya, koordinator membagi dengan cepat, semua siap membantu di luar bagiannya"],answer:2,explain:"Di situasi cepat, berbagi tugas berarti fleksibilitas: semua siap mengisi celah, bukan berpegang kaku pada pembagian.",hint:"Fleksibel & siap mengisi celah, atau 'bukan bagianku' / menunggu rapat?"},
{n:57,type:"tf",micro:"Berbagi tugas tidak menghapus tanggung jawab pribadi",q:"Benar atau Salah: Setelah tugas dibagi, tanggung jawab menyelesaikan tiap bagian pindah sepenuhnya ke koordinator; anggota hanya perlu mengerjakan bila diingatkan.",answer:false,explain:"Sebaliknya, berbagi tugas = berbagi tanggung jawab, bukan memindahkannya. Kamu memegang bagianmu, jadi kamu yang memastikannya selesai sesuai standar & tenggat serta mengabari kendala.",hint:"Tetap bertanggung jawab pada bagianmu, atau lepas ke koordinator?"},
{n:58,type:"mcq",micro:"Skenario: berbagi beban di kelompok belajar",q:"Kelompok belajar untuk ujian: cara berbagi yang efektif:",options:["Tiap orang mendalami & menyiapkan ringkasan satu topik, lalu mengajarkannya ke yang lain (jigsaw) — semua belajar semua, beban terbagi","Satu orang membuat semua ringkasan untuk semua topik, sedangkan anggota lain tinggal menyalin & menghafalkannya sebelum ujian dimulai","Semua anggota belajar semua topik sendiri-sendiri tanpa berbagi, supaya masing-masing bertanggung jawab atas kemampuannya sendiri di ujian nanti"],answer:0,explain:"Metode 'jigsaw' (tiap orang ahli satu bagian lalu mengajarkan) membagi beban penyiapan & memperkuat pemahaman semua.",hint:"Tiap orang siapkan & ajarkan satu topik, atau satu bikin semua / tak berbagi?"},
{n:59,type:"mcq",micro:"Skenario: menolak berbagi kredit",q:"Seorang anggota ingin namanya saja yang disebut sebagai pembuat karya, padahal tim mengerjakannya bersama. Sikap tim:",options:["Semua anggota mengklaim bahwa karya itu buatannya, sehingga nama mereka tertulis sebagai pembuat utama masing-masing","Ingatkan bahwa ini kerja bersama & kontribusi semua perlu diakui; sepakati cara menyebut kontribusi yang adil","Biarkan saja namanya yang disebut, karena dialah yang paling banyak bekerja dan yang lain tak perlu dicantumkan"],answer:1,explain:"Berbagi kredit secara adil menjaga semangat & keadilan tim. Mengklaim sepihak merusak kepercayaan.",hint:"Ingatkan kerja bersama + akui semua, atau biarkan / semua klaim sendiri?"},
{n:60,type:"open",micro:"Memperbaiki cara tim berbagi",q:"Timmu selama ini membagi tugas dengan cara: koordinator menunjuk cepat di grup chat tanpa membahas beban, tidak ada tenggat internal, file tersebar di laptop masing-masing, dan info penting sering hanya diketahui sebagian orang. Tulis minimal 5 perubahan konkret untuk cara tim berbagi tugas & sumber daya, dengan alasan.",explain:"Jawaban baik memberi minimal 5 perubahan konkret dengan alasan: pertemuan pembagian dengan perkiraan beban bersama, cocokkan kekuatan+waktu & cek keseimbangan, tenggat internal bertahap, satu tempat penyimpanan bersama + aturan versi, satu kanal info utama + notulen wajib, budaya saling bantu (yang selesai membantu, yang kewalahan minta bantuan), berbagi hasil lebih awal.",hint:"Ubah tiap kelemahan: penunjukan cepat→pertemuan pembagian dengan perkiraan beban; tak ada tenggat→tenggat internal bertahap; file tersebar→penyimpanan bersama; info sebagian→satu kanal + notulen.",sample:"(1) Ganti 'koordinator menunjuk cepat' dengan pertemuan pembagian: daftar semua pekerjaan bersama, perkirakan beban tiap bagian, baru bagi dengan semua ikut menimbang. Alasan: pembagian yang dibahas bersama lebih adil & terasa adil. (2) Cocokkan bagian dengan kekuatan & ketersediaan waktu tiap anggota, lalu cek 'apakah beban tiap orang kira-kira sebanding?' sebelum finalisasi. Alasan: menangkap ketimpangan sebelum jadi masalah. (3) Tetapkan tenggat internal per bagian, beberapa hari sebelum tenggat asli, dan susun bertahap sesuai bagian yang saling bergantung. Alasan: beban tidak menumpuk di akhir & bagian bisa dicek. (4) Pindahkan semua file ke satu tempat penyimpanan bersama yang semua bisa akses & edit, dengan satu file utama dan aturan penamaan versi. Alasan: mencegah 'file ketimpa' & tim tidak macet kalau satu laptop tidak ada. (5) Sepakati satu kanal utama untuk semua info proyek; keputusan & info penting wajib ditulis di situ (bukan japri), dan yang tidak hadir rapat wajib membaca notulen. Alasan: semua punya informasi yang sama. (6) Sepakati bahwa yang selesai lebih dulu menawarkan bantuan, dan yang kewalahan wajib minta bantuan lebih awal. Alasan: beban diseimbangkan sepanjang proyek, bukan dibiarkan jatuh pada 'yang rela'. (7) Bagikan hasil bagian masing-masing beberapa hari sebelum tenggat untuk dicek bersama."},
{n:61,type:"mcq",micro:"Mengapa memecah pekerjaan dulu",q:"Mengapa mendaftar & memecah semua pekerjaan sebelum membagi itu penting?",options:["Karena daftar pekerjaan membuat dokumen proyek terlihat lebih rapi, sehingga guru lebih terkesan","Tidak penting; langsung bagi saja tugas berdasarkan perkiraan, dan kekurangannya diperbaiki bila ketahuan nanti","Kamu tidak bisa menilai apakah pembagian adil atau lengkap kalau belum tahu total pekerjaannya"],answer:2,explain:"Membagi tanpa peta lengkap sering menghasilkan bagian yang terlewat & beban yang timpang tanpa disadari.",hint:"Perlu peta lengkap untuk membagi adil, atau langsung bagi?"},
{n:62,type:"mcq",micro:"Mengapa menimbun sumber merugikan tim",q:"Mengapa menyimpan referensi/keterampilan sendiri (tidak berbagi ke tim) merugikan hasil tim?",options:["Sumber yang dibagikan dipakai berkali-kali oleh banyak anggota; yang disimpan hanya menguntungkan satu orang & membuat yang lain mengulang usaha yang sama","Tidak merugikan, karena itu hak pribadi tiap orang dan hasil tim tidak akan terpengaruh oleh apa yang disimpan sendiri, selama bagian miliknya selesai tepat waktu","Menimbun justru mempercepat tim, karena anggota lain jadi tidak terganggu oleh informasi yang berlebihan & bisa fokus pada bagiannya saja"],answer:0,explain:"Dalam tim, keunggulan pribadi yang ditahan adalah kerugian kolektif. Tujuan tim adalah hasil bersama.",hint:"Sumber dibagikan berlipat guna, atau menimbun tak merugikan?"},
{n:63,type:"tf",micro:"Keadilan beban vs keadilan hasil",q:"Benar atau Salah: Dalam tim, 'adil' lebih tepat diartikan sebagai beban yang sebanding & proses pembagian yang transparan, bukan tiap orang mengerjakan hal yang persis identik.",answer:true,explain:"Memaksa keseragaman ('semua harus bikin 1 slide yang sama') sering tidak efisien & malah tidak adil bila kesulitan tiap bagian berbeda.",hint:"Beban sebanding + transparan, atau identik?"},
{n:64,type:"mcq",micro:"Menilai pembagian yang baik",q:"Tanda pembagian tugas berjalan baik:",options:["Semua bagian dikerjakan oleh dua orang sekaligus supaya 'aman', sehingga tidak ada bagian yang terlewat walaupun banyak pekerjaan yang dobel","Tidak ada bagian yang terlewat, tidak ada yang kelewat kewalahan atau menganggur, & semua merasa proses pembagiannya adil","Satu orang mengerjakan 70% pekerjaan sedangkan lainnya sedikit, tetapi semua mengaku tidak keberatan, sehingga dianggap pembagian sudah berjalan baik"],answer:1,explain:"Pembagian yang baik: cakupan lengkap + beban seimbang + rasa adil. Bukan ketergantungan pada satu orang atau kerja ganda.",hint:"Cakupan lengkap + seimbang + adil, atau menumpuk / ganda?"},
{n:65,type:"mcq",micro:"Mengapa tenggat bertahap membantu",q:"Mengapa menyusun tenggat internal bertahap lebih baik daripada satu tenggat besar di akhir?",options:["Membuat proyek terasa lebih menekan karena pekerjaan harus dicicil dan dicek berulang-ulang setiap minggunya","Tidak ada bedanya, karena proyek selesai pada waktu yang sama baik dicicil maupun dikerjakan sekaligus","Beban tersebar sepanjang waktu (tidak menumpuk), bagian yang bergantung punya urutan, & masalah ketahuan lebih awal"],answer:2,explain:"Satu tenggat besar mendorong semua kerja di detik terakhir & menyembunyikan masalah sampai terlambat.",hint:"Beban tersebar + urutan + masalah dini, atau lebih menekan / sama saja?"},
{n:66,type:"tf",micro:"Membagi tugas = tidak perlu koordinasi lagi?",q:"Benar atau Salah: Setelah tugas dibagi jelas, tim tidak perlu lagi berkoordinasi — cukup tiap orang menyelesaikan bagiannya masing-masing.",answer:false,explain:"Sebaliknya, bagian-bagian harus nyambung jadi satu. Koordinasi & update rutin memastikan tidak ada yang menyimpang atau kejutan di akhir.",hint:"Tak perlu koordinasi lagi, atau tetap perlu?"},
{n:67,type:"mcq",micro:"Berbagi & ketahanan tim",q:"Tim yang anggotanya berbagi keterampilan & informasi secara terbuka menjadi lebih tahan banting karena...",options:["Bila satu anggota tidak ada, orang lain bisa melanjutkan bagiannya; tidak ada 'titik kegagalan tunggal'","Karena anggota tim yang berbagi tidak membuat kesalahan, sehingga tidak ada bagian yang perlu dilanjutkan orang lain","Berbagi tidak memengaruhi ketahanan tim, sebab ketahanan ditentukan jumlah anggota dan seberapa keras mereka bekerja"],answer:0,explain:"Pengetahuan yang tersebar = tim yang bisa bertahan saat ada yang absen. Pengetahuan yang terpusat = rapuh.",hint:"Tidak ada titik kegagalan tunggal, atau tak berpengaruh?"},
{n:68,type:"mcq",micro:"Menilai apakah bantuan diperlukan atau mengambil alih",q:"Beda 'membantu anggota yang kewalahan' & 'mengambil alih bagiannya':",options:["Mengambil alih lebih baik, karena hasilnya lebih rapi dan cepat; anggota yang lamban sebaiknya tidak diberi kesempatan mengerjakannya lagi, sehingga tim tidak terhambat","Membantu: mendampingi, mengerjakan sebagian bersama, tetap ia yang memegang. Mengambil alih diam-diam: mengerjakan semuanya untuknya tanpa bilang, membuatnya tidak belajar & bingung","Keduanya sama, karena sama-sama membantu teman menyelesaikan bagiannya; yang penting bagian itu selesai tepat waktu dan terlihat bagus saat dikumpulkan kepada guru oleh tim"],answer:1,explain:"Bantuan menjaga rasa memiliki & pembelajaran anggota; mengambil alih tanpa komunikasi merusak keduanya.",hint:"Mendampingi vs mengerjakan semuanya diam-diam, atau sama saja?"},
{n:69,type:"mcq",micro:"Berbagi tugas & keadilan yang dirasakan",q:"Anggota lebih menerima bahwa bagiannya lebih berat bila...",options:["Diputuskan diam-diam oleh koordinator tanpa melibatkan anggota lain, lalu langsung diumumkan sebagai keputusan yang tidak boleh dibantah lagi","Ia tidak diberi tahu kenapa bagiannya lebih berat, tetapi diminta menerima saja karena memang sudah begitu dari sananya","Prosesnya transparan (semua ikut menimbang), alasannya jelas (mis. ia yang paling ahli / punya paling banyak waktu), & ada kompensasi di bagian lain bila perlu"],answer:2,explain:"Rasa adil datang dari proses yang terbuka & alasan yang masuk akal, bukan hanya dari angka beban.",hint:"Transparan + beralasan + kompensasi, atau diam-diam / tanpa penjelasan?"},
{n:70,type:"order",micro:"Menangani sumber daya yang tidak cukup untuk semua",q:"Urutkan cara tim menangani sumber daya (mis. 1 komputer) yang tidak cukup untuk semua sekaligus.",items:["Identifikasi bagian mana yang benar-benar butuh sumber daya itu & kapan","Susun jadwal pemakaian berdasarkan kebutuhan & urutan pekerjaan","Atur agar yang menunggu mengerjakan bagian yang tidak butuh sumber daya itu","Tinjau jadwal bila kebutuhan berubah, & rapikan setelah dipakai untuk yang berikutnya"],answer:[0,1,2,3],explain:"Identifikasi kebutuhan → jadwal → kerja paralel bagi yang menunggu → tinjau & rapikan. Sumber daya terbatas dimaksimalkan.",hint:"Apa yang diidentifikasi sebelum menyusun jadwal?"},
{n:71,type:"mcq",micro:"Berbagi tugas & motivasi",q:"Anggota yang mendapat bagian yang cocok dengan kekuatannya & merasa pembagiannya adil cenderung...",options:["Lebih termotivasi & menghasilkan kerja yang lebih baik","Lebih malas karena merasa nyaman dan dihargai tanpa bekerja","Mulai kehilangan minat karena tidak ada tantangan"],answer:0,explain:"Pembagian yang adil & cocok menyalakan motivasi. Pembagian yang timpang atau tidak cocok memadamkannya.",hint:"Lebih termotivasi, atau lebih malas?"},
{n:72,type:"tf",micro:"Berbagi hasil awal mengurangi risiko",q:"Benar atau Salah: Ketika anggota berbagi draf bagiannya lebih awal, tim bisa menemukan bagian yang tidak nyambung atau salah arah saat masih ada waktu memperbaikinya.",answer:true,explain:"Menggabungkan semua bagian di menit terakhir sering mengungkap ketidakcocokan yang tidak sempat diperbaiki.",hint:"Menemukan masalah saat masih ada waktu, atau tidak berpengaruh?"},
{n:73,type:"mcq",micro:"Berbagi tugas di tim besar vs kecil",q:"Di tim besar (8+ orang), berbagi tugas...",options:["Tidak mungkin dibagi, karena terlalu banyak orang untuk dikoordinasi","Lebih butuh struktur: sub-tim, penanggung jawab tiap sub-tim, & koordinasi antar sub-tim","Sama saja dengan tim kecil, jadi tanpa struktur tambahan pun cukup untuk delapan orang"],answer:1,explain:"Tim besar sulit dikoordinasi sebagai satu blok. Memecah jadi sub-tim membuat pembagian & komunikasi lebih terkelola.",hint:"Butuh struktur sub-tim, atau sama saja?"},
{n:74,type:"mcq",micro:"Menilai 'yang penting selesai'",q:"Sikap 'yang penting semua bagian selesai, tidak peduli siapa mengerjakan berapa' bermasalah karena...",options:["Sikap itu justru paling efisien dan adil, karena perhatian tim fokus pada penyelesaian, bukan pada siapa yang mengerjakan lebih banyak","Tidak bermasalah selama hasil akhirnya selesai tepat waktu dan guru tidak mengetahui pembagian yang timpang di tim","Mengabaikan keadilan beban & pembelajaran; anggota yang menanggung berlebihan jadi lelah/kesal, yang lain tidak berkembang"],answer:2,explain:"Hasil satu proyek mungkin jadi, tapi pola menumpuk beban tidak berkelanjutan & merusak tim jangka panjang.",hint:"Mengabaikan keadilan & pembelajaran, atau paling efisien?"},
{n:75,type:"tf",micro:"Berbagi menyeimbangkan lintas waktu",q:"Benar atau Salah: Keadilan pembagian tugas bisa diseimbangkan sepanjang durasi proyek — seorang anggota mengambil lebih banyak di minggu ia luang, dan lebih sedikit di minggu ia sibuk — asalkan disepakati & totalnya sebanding.",answer:true,explain:"Fleksibilitas lintas waktu (dengan kesepakatan) membuat pembagian adil sekaligus realistis terhadap kesibukan yang berubah.",hint:"Bisa diseimbangkan lintas waktu, atau harus sama tiap minggu?"},
{n:76,type:"mcq",micro:"Berbagi & konflik",q:"Banyak konflik dalam kerja kelompok berakar dari...",options:["Pembagian tugas yang timpang atau tidak jelas, & sumber daya/informasi yang tidak dibagi merata","Anggota yang terlalu banyak berbagi sumber daya membuat tim bergantung dan saling bertengkar soal itu","Tidak ada hubungannya dengan pembagian tugas; konflik berasal dari sifat bawaan orang dan tak bisa dicegah"],answer:0,explain:"'Kenapa aku ngerjain banyak, dia sedikit?' & 'kenapa aku nggak dikasih tahu?' adalah bahan bakar utama pertengkaran tim.",hint:"Pembagian timpang & info tidak merata, atau terlalu banyak berbagi?"},
{n:77,type:"mcq",micro:"Berbagi tugas & tujuan tim",q:"Pembagian tugas melayani tujuan tim ketika...",options:["Setiap orang fokus pada bagiannya tanpa peduli hasil akhir, selama bagian masing-masing sudah dikerjakan baik","Setiap bagian jelas mendukung hasil akhir, & tim tetap bisa menyesuaikan pembagian bila itu membantu proyek","Pembagian dipertahankan kaku seperti semula walau menghambat proyek, sebab mengubahnya dianggap tim tidak konsisten"],answer:1,explain:"Pembagian adalah alat untuk mencapai hasil, bukan tujuan itu sendiri. Ia menyesuaikan diri demi proyek.",hint:"Melayani hasil & bisa disesuaikan, atau kaku / tak peduli hasil?"},
{n:78,type:"mcq",micro:"Berbagi & rasa dihargai",q:"Ketika kontribusi tiap anggota (di bagian masing-masing) diakui secara terbuka, efeknya:",options:["Membuat anggota sombong dan merasa lebih penting daripada anggota yang lain di tim","Tidak ada efeknya, karena penghargaan hanya formalitas dan tidak memengaruhi semangat","Anggota merasa dihargai & lebih mau berkontribusi penuh di proyek berikutnya"],answer:2,explain:"Berbagi kredit secara adil adalah bagian dari berbagi yang menjaga tim tetap sehat & termotivasi.",hint:"Merasa dihargai & mau kontribusi lagi, atau sombong / tak berefek?"},
{n:79,type:"mcq",micro:"Menilai apakah berbagi terlalu jauh",q:"Berbagi sumber daya pribadi (alat, uang, waktu) ke tim itu baik, TAPI...",options:["Kamu berhak menetapkan batas yang kamu nyaman & tidak wajib mengorbankan diri berlebihan; berbagi yang sehat bukan berarti dieksploitasi","Kamu wajib memberikan yang diminta tim kapan saja tanpa batas, karena menolak berarti kamu bukan anggota tim yang baik, walaupun merugikan dirimu","Kamu tidak boleh berbagi dengan tim, karena milik pribadi harus dijaga sendiri dan berbagi hanya merugikan dirimu, apalagi pada tugas kelompok"],answer:0,explain:"Berbagi yang sehat ada dalam batas. Anggota yang terus 'nombok' & meminjamkan tanpa batas bisa dimanfaatkan.",hint:"Berbagi dengan batas yang kamu nyaman, atau wajib apa pun / tidak sama sekali?"},
{n:80,type:"open",micro:"Menganalisis dua tim",q:"Tim A: koordinator menunjuk tugas cepat, tidak ada perkiraan beban, satu anggota akhirnya mengerjakan setengah proyek, referensi & template disimpan masing-masing. Tim B: mendaftar pekerjaan bersama, memperkirakan beban, membagi sesuai kekuatan + ketersediaan, memakai satu tempat penyimpanan bersama, dan yang selesai duluan membantu yang lain. Jelaskan mengapa Tim B kemungkinan menghasilkan proyek lebih baik & anggota lebih puas (minimal 4 alasan), dan 1 risiko yang tetap bisa terjadi di Tim B.",explain:"Jawaban baik memberi minimal 4 alasan Tim B unggul (beban adil dari perkiraan bersama, tugas cocok kekuatan+waktu, penyimpanan bersama = tidak macet + tidak mengulang usaha, budaya saling bantu menyeimbangkan, proses transparan mengurangi konflik) dan 1 risiko yang tersisa (tanpa cek kemajuan, perkiraan beban yang meleset tetap bisa membuat seseorang kewalahan diam-diam — perlu peninjauan di tengah).",hint:"Alasan B unggul: beban adil, tugas cocok, penyimpanan bersama, budaya saling bantu, transparansi. Risiko tersisa: perkiraan beban bisa meleset tanpa cek kemajuan.",sample:"Tim B kemungkinan lebih baik & anggotanya lebih puas karena: (1) Beban terbagi adil berdasarkan perkiraan bersama, jadi tidak ada satu orang yang kelelahan mengerjakan setengah proyek seperti di Tim A, dan tidak ada yang merasa proses pembagiannya sewenang-wenang. (2) Tugas dicocokkan dengan kekuatan & ketersediaan, jadi tiap bagian dikerjakan oleh orang yang paling pas & hasilnya lebih baik. (3) Satu tempat penyimpanan bersama berarti semua bisa mengakses & melanjutkan pekerjaan, tim tidak macet kalau satu orang tidak ada, dan tidak ada usaha yang diulang karena referensi tersembunyi. (4) Budaya 'yang selesai membantu yang lain' menyeimbangkan beban sepanjang proyek & mempercepat penyelesaian, sekaligus membuat anggota merasa didukung. (5) Karena prosesnya transparan, konflik 'kenapa aku ngerjain banyak' jauh lebih kecil. Risiko yang tetap bisa terjadi di Tim B: meski pembagiannya adil di awal, bila tidak ada cek kemajuan rutin, sebuah bagian bisa ternyata jauh lebih berat dari perkiraan dan orang itu tetap kewalahan tanpa ketahuan sampai terlambat — jadi Tim B tetap perlu meninjau & menyeimbangkan ulang di tengah jalan."},
{n:81,type:"mcq",micro:"Kasus: sumber daya diberikan tidak adil oleh keadaan",q:"Dalam tim, satu anggota kebetulan punya semua sumber daya (laptop bagus, internet cepat, printer, waktu luang) & yang lain sangat terbatas. Sikap tim yang adil:",options:["Yang punya sumber daya terbatas dikeluarkan dari tim karena tidak banyak membantu, dan sisanya yang lengkap bekerja lebih cepat tanpa dia, lalu hasilnya dicantumkan atas nama seluruh tim","Anggota yang punya lebih menawarkan berbagi sumber dayanya (dalam batas nyaman); pembagian tugas menyesuaikan agar yang terbatas tetap bisa berkontribusi penuh lewat bagian yang cocok","Yang punya sumber daya lengkap mengerjakan semua bagian sendirian, sedangkan yang terbatas menunggu hasilnya jadi lalu ikut menyebut namanya di laporan akhir kelompok yang dikumpulkan"],answer:1,explain:"Ketimpangan sumber daya nyata diatasi dengan berbagi + menyesuaikan pembagian, bukan menumpuk atau menyingkirkan.",hint:"Berbagi + sesuaikan pembagian, atau satu orang semua / singkirkan?"},
{n:82,type:"mcq",micro:"Kasus: berbagi tugas dengan anggota yang tidak bisa diandalkan",q:"Seorang anggota punya rekam jejak tidak menepati bagian. Cara membagi yang bijak:",options:["Beri dia bagian paling sulit dan terpenting sekaligus untuk membuktikan diri, walaupun bila ia telat seluruh tim ikut macet seketika, dan nanti dibahas bila terjadi","Jangan beri dia bagian apa pun karena ia sudah terbukti tidak bisa dipercaya, dan anggota lain menanggung semuanya tanpa dia, sampai proyek ini selesai","Beri bagian yang penting tapi TIDAK menjadi 'jalur kritis' (yang lain tidak lumpuh bila ia telat); tetap cek kemajuannya lebih sering; sepakati langkah bila ia gagal lagi"],answer:2,explain:"Manajemen risiko: anggota yang berisiko diberi tanggung jawab nyata tapi ditempatkan di posisi yang dampak kegagalannya lebih terbatas, dengan pemantauan lebih.",hint:"Bagian nyata tapi bukan jalur kritis + cek lebih sering, atau bagian terpenting / tidak sama sekali?"},
{n:83,type:"tf",micro:"Refleksi: berbagi = inti kerja sama",q:"Benar atau Salah: Membagi tugas dengan adil & berbagi sumber daya secara terbuka hanyalah formalitas; inti kerja sama sebenarnya cukup soal masing-masing menyelesaikan bagiannya.",answer:false,explain:"Sebaliknya, tim yang tidak berbagi (tugas timpang, info & sumber ditahan) sebenarnya hanya sekumpulan individu yang bekerja berdekatan. Berbagi adalah inti kerja sama efektif.",hint:"Inti kerja sama, atau hal kecil?"},
{n:84,type:"mcq",micro:"Kasus: berbagi tugas saat proyek berubah drastis",q:"Di tengah proyek, guru mengubah persyaratan drastis & separuh pekerjaan lama jadi tidak terpakai. Sikap tim:",options:["Kumpul, daftar ulang pekerjaan yang sekarang dibutuhkan, bagi ulang dari awal dengan mempertimbangkan siapa sudah punya beban berapa, sesuaikan tenggat","Tetap kerjakan pembagian lama seperti semula karena sudah disepakati bersama, meskipun sebagian pekerjaan itu sudah tidak dibutuhkan lagi oleh guru","Menyalahkan guru yang mengubah persyaratan dan tidak membagi ulang, lalu mengumpulkan hasil apa adanya sebagai protes"],answer:0,explain:"Perubahan besar membutuhkan pembagian ulang, bukan berpegang pada pembagian yang sudah tidak relevan.",hint:"Bagi ulang dari daftar baru, atau tetap pembagian lama / menyalahkan?"},
{n:85,type:"order",micro:"Berbagi tugas untuk kegiatan berulang jangka panjang",q:"Urutkan langkah menyusun sistem pembagian tugas yang adil untuk kegiatan mingguan (mis. mengelola mading kelas selama setahun).",items:["Daftar semua tugas rutin & perkirakan beban masing-masing","Buat jadwal rotasi tertulis sehingga tiap orang mendapat variasi tugas & beban sepanjang tahun","Sepakati aturan menukar/mencari pengganti bila berhalangan","Tinjau sistem tiap beberapa bulan: adil? ada yang selalu kena tugas berat?"],answer:[0,1,2,3],explain:"Daftar & perkiraan → jadwal rotasi → aturan tukar → tinjauan berkala. Kegiatan jangka panjang butuh sistem, bukan penunjukan berulang.",hint:"Apa yang didaftar sebelum membuat jadwal rotasi?"},
{n:86,type:"mcq",micro:"Kasus: berbagi ke tim lawan/pesaing?",q:"Dalam lomba antar kelompok, satu kelompok kekurangan alat & memintamu meminjamkan. Sikap:",options:["Wajib memberikan yang diminta kelompok lain tanpa mempertimbangkan aturan lomba atau kebutuhan timmu, karena kebaikan harus diutamakan dalam situasi apa saja","Kamu boleh membantu bila itu tidak melanggar aturan lomba & tidak merugikan timmu — sportivitas & kebaikan bisa berdampingan dengan kompetisi; diskusikan dulu dengan timmu","Wajib menolak mentah-mentah karena mereka pesaingmu dalam lomba, & membantu mereka sama saja dengan mengkhianati timmu sendiri dengan sengaja"],answer:1,explain:"Berbagi lintas tim adalah pilihan sportif yang wajar dalam batas aturan & kepentingan timmu — bukan kewajiban, bukan larangan mutlak.",hint:"Boleh bila tidak melanggar aturan & merugikan tim (diskusi dulu), atau wajib tolak / wajib beri?"},
{n:87,type:"tf",micro:"Berbagi tugas tidak sama dengan menyalin (tugas individu)",q:"Benar atau Salah: Untuk tugas INDIVIDU, berbagi berhenti pada bertukar pemahaman & saling menjelaskan; menyalin jawaban atau mengerjakan bagian orang lain untuknya adalah kecurangan, bukan kerja sama.",answer:true,explain:"Kerja sama yang sah pada tugas individu = belajar bersama, berdiskusi, saling menjelaskan. Bukan menghasilkan karya untuk orang lain.",hint:"Bertukar pemahaman (sah) vs menyalin jawaban (curang), atau sama saja?"},
{n:88,type:"mcq",micro:"Kasus: kamu selalu memberi lebih",q:"Kamu menyadari kamu selalu jadi yang berbagi paling banyak (referensi, bantuan, alat) & mulai merasa dimanfaatkan. Sikap:",options:["Berhenti berbagi secara tiba-tiba tanpa penjelasan kepada tim, supaya mereka menyadari betapa selama ini mereka bergantung padamu","Terus memberi seperti biasa sambil menyimpan kesal di dalam hati tanpa mengatakannya, karena menolak dianggap egois oleh anggota lain","Sampaikan ke tim dengan jujur; ajak semua ikut berbagi & membantu; tetapkan batas berbagi yang kamu nyaman — berbagi sehat itu timbal balik"],answer:2,explain:"Berbagi yang sehat mengalir dua arah. Menyuarakan ketidakseimbangan & menetapkan batas menjaga dirimu tanpa merusak tim.",hint:"Suarakan + ajak timbal balik + batas, atau berhenti diam-diam / memberi sambil kesal?"},
{n:89,type:"mcq",micro:"Kasus: menggabungkan bagian yang gaya-nya berbeda",q:"Bagian-bagian anggota selesai tapi gayanya sangat berbeda (font, warna, cara menulis). Cara menangani:",options:["Idealnya sepakati gaya seragam di AWAL sebelum masing-masing mengerjakan; kalau sudah terlanjur, tugaskan satu orang menyeragamkan & hitung itu sebagai beban","Biarkan saja berbeda-beda gayanya karena itulah kekayaan tim, dan guru nanti akan memahami bahwa tiap anggota punya selera masing-masing, jadi tidak perlu dibahas","Suruh semua anggota mengerjakan ulang bagiannya dari nol tanpa panduan gaya, sampai tampilannya sama persis walaupun waktu sudah mepet sekali"],answer:0,explain:"Ketidakcocokan gaya adalah biaya dari tidak menyepakati standar di awal. Cegah di awal; kalau terlanjur, tugaskan penyeragaman sebagai pekerjaan nyata.",hint:"Sepakati gaya di awal / tugaskan penyeragaman, atau biarkan / ulang total?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu ketua tim 6 orang untuk proyek besar 4 minggu. Kondisi: kemampuan sangat beragam, 2 anggota sangat sibuk (ekskul & kerja paruh waktu), sumber daya terbatas (2 laptop, 1 ruang kerja 2 jam/hari), dan proyek butuh riset + pembuatan + presentasi. Rancang sistem berbagi tugas & sumber daya yang adil dan efisien. Minimal 6 keputusan konkret dengan alasan.",explain:"Jawaban baik memuat minimal 6 keputusan konkret dengan alasan yang menangani KEDUA sisi: pembagian TUGAS (daftar + perkirakan beban, cocokkan kekuatan+ketersediaan dengan yang sibuk pegang bagian kecil-fleksibel, pasangan mentor-asisten dengan berbagi cara, tenggat bertahap + cek, berbagi draf awal, pembagian presentasi adil) dan pembagian SUMBER DAYA (jadwal ruang bergilir sesuai prioritas + rapikan, pembagian laptop + penyimpanan bersama + aturan versi + satu penggabung), plus kepemimpinan yang menyeimbangkan & mengakui kontribusi.",hint:"Tangani tugas (daftar+beban, cocokkan kekuatan+waktu dengan yang sibuk pegang bagian kecil, mentor-asisten berbagi cara, tenggat bertahap, draf awal, presentasi adil) DAN sumber daya (jadwal ruang bergilir, aturan laptop+file bersama).",sample:"(1) Pertemuan pembagian: daftar SEMUA pekerjaan (riset, pengumpulan data, pembuatan materi/karya, penulisan, desain, penggabungan, latihan presentasi, presentasi), lalu perkirakan bersama beban tiap bagian dalam jam/kesulitan. Alasan: tidak bisa membagi adil tanpa peta lengkap & perkiraan beban. (2) Bagi sesuai kekuatan + ketersediaan: 2 anggota sibuk pegang bagian yang lebih kecil, fleksibel waktunya, dan bisa dikerjakan sepotong-sepotong (mis. menulis satu sub-bagian, mengumpulkan sumber tertentu); anggota yang lebih luang pegang bagian yang butuh jam kerja lebih (riset mendalam, pembuatan, penggabungan). Cek 'apakah total beban tiap orang sebanding' sebelum finalisasi. Alasan: adil = sebanding & realistis terhadap kesibukan. (3) Pasangkan anggota yang ahli dengan yang kurang ahli di bagian inti (mentor-asisten), dan yang ahli WAJIB berbagi caranya, bukan hanya hasilnya. Alasan: hasil kuat + semua belajar + tim tidak bergantung pada satu orang. (4) Jadwal ruang kerja 2 jam/hari: bagi ke pasangan/kelompok kecil sesuai bagian yang paling butuh ruang minggu itu (mis. minggu 1-2 tim riset & pembuatan, minggu 3 tim desain & penggabungan, minggu 4 latihan presentasi bersama); yang tidak di ruang mengerjakan bagian yang bisa di rumah/perpustakaan. Aturan: rapikan ruang untuk kelompok berikutnya. Alasan: sumber daya terbatas dipakai bergilir sesuai prioritas & tidak menganggur. (5) 2 laptop: satu untuk riset/penulisan, satu untuk desain; semua file di satu penyimpanan bersama dengan satu file utama + aturan penamaan versi + satu orang yang menggabungkan perubahan. Alasan: mencegah 'file ketimpa' & tim tidak macet. (6) Tenggat internal bertahap (riset minggu 1, pembuatan minggu 2-3, penggabungan minggu 3, latuxan minggu 4), cek kemajuan 2x seminggu. Semua bagikan draf beberapa hari sebelum tenggat bagian untuk dicek. Alasan: beban merata, urutan ketergantungan terjaga, masalah ketahuan dini. (7) Bagian presentasi dibagi sesuai bagian yang dikerjakan, porsi waktu bicara sebanding, dengan latihan bersama; anggota yang gugup dapat bagian lebih pendek + peran pendukung. (8) Sebagai ketua, aku menjaga keseimbangan beban sepanjang proyek, membantu bagian yang tertinggal, memastikan info penting ada di kanal bersama, dan mengakui kontribusi tiap orang saat presentasi."},
{n:91,type:"mcq",micro:"Kasus: berbagi tugas & anggota yang merasa bagiannya 'kecil'",q:"Seorang anggota merasa bagiannya 'terlalu kecil & tidak penting' & ingin lebih. Sikap:",options:["Beri dia semua bagian yang tidak diinginkan anggota lain, supaya ia merasa dibutuhkan, walaupun bebannya sudah terlalu berat","Tinjau bersama: bila memang bebannya kurang, tambahkan tugas atau bagian yang lebih menantang; hargai keinginannya berkontribusi lebih","Biarkan saja keinginannya, karena mungkin dia hanya mencari perhatian teman-teman dan nanti akan hilang sendiri dalam beberapa hari"],answer:1,explain:"Anggota yang ingin berkontribusi lebih adalah aset. Tinjau & seimbangkan ulang dengan memberinya bagian yang berarti.",hint:"Tinjau + tambahkan bagian berarti, atau abaikan / beri sisa yang tak diinginkan?"},
{n:92,type:"tf",micro:"Refleksi: berbagi mengalir dua arah",q:"Benar atau Salah: Berbagi yang sehat dalam tim bersifat timbal balik — tiap anggota bersedia memberi (tugas, bantuan, sumber, info) DAN menerima (bantuan, umpan balik, bagian yang bukan pilihannya).",answer:true,explain:"Tim di mana hanya sebagian orang yang memberi & sebagian hanya menerima akan timpang & menimbulkan kekesalan.",hint:"Timbal balik, atau satu arah?"},
{n:93,type:"mcq",micro:"Kasus: kamu tergoda menimbun keunggulan",q:"Kamu punya template & trik yang membuat bagianmu selalu terlihat paling bagus, & tergoda tidak membagikannya. Pertimbangan yang tepat:",options:["Simpan saja template dan trikmu sendiri, karena itu keunggulanmu dan alasan bagianmu dinilai paling bagus oleh guru dibanding yang lain di kelas","Bagikan, tetapi versi yang sudah kamu rusak sebagian, supaya mereka tidak bisa melampaui hasil bagianmu sambil tetap tampak membantu","Dalam tim, hasil bersama adalah tujuannya; berbagi trikmu membuat seluruh proyek lebih baik & membangun reputasimu sebagai anggota yang murah hati & berharga"],answer:2,explain:"Menimbun keunggulan di dalam tim adalah bersaing melawan timmu sendiri. Berbagi memperkuat hasil & hubungan.",hint:"Berbagi demi hasil bersama & reputasi, atau simpan / bagikan versi rusak?"},
{n:94,type:"mcq",micro:"Kasus: menilai kembali pembagian di akhir",q:"Menjelang akhir proyek, kamu sadar pembagian ternyata timpang (kamu & satu teman mengerjakan jauh lebih banyak). Sikap yang membangun:",options:["Selesaikan proyek dulu dengan baik, lalu di refleksi tim sampaikan jujur & tanpa menyerang: 'Pembagian kita ternyata timpang; lain kali kita cek beban di awal & di tengah'","Diam saja dan menyimpan kesal terus-menerus tanpa membahasnya dengan tim, sebab membicarakan ketimpangan hanya merusak suasana kekompakan, walau proyeknya sudah selesai","Menolak menyelesaikan proyek sebagai bentuk protes kepada tim, supaya semua anggota sadar bahwa pembagian mereka sangat tidak adil bagimu"],answer:0,explain:"Selesaikan komitmen, lalu jadikan ketimpangan itu pelajaran tim untuk proyek berikutnya — bukan dipendam atau dijadikan alasan menggagalkan proyek.",hint:"Selesaikan + refleksi jujur untuk lain kali, atau pendam / mogok?"},
{n:95,type:"tf",micro:"Berbagi tugas melayani hasil & orang",q:"Benar atau Salah: Selama proyek akhirnya selesai, tidak penting apakah pembagian tugasnya adil atau apakah sebagian anggota kelelahan & kesal.",answer:false,explain:"Sebaliknya, sistem berbagi yang baik menghasilkan DUA hal: proyek selesai baik & efisien, DAN tiap anggota merasa diperlakukan adil serta ikut berkembang. Kalau sebagian kelelahan & kesal, sistemnya belum berhasil.",hint:"Hasil + orang, atau hasil saja?"},
{n:96,type:"mcq",micro:"Kasus: refleksi soal berbagi",q:"Cara melatih dirimu jadi anggota tim yang lebih baik dalam berbagi:",options:["Mengabaikan evaluasi kebiasaan berbagimu setelah proyek selesai, karena yang penting nilai sudah keluar dan proyek berikutnya akan berbeda jauh, jadi tidak perlu dibahas","Setelah tiap proyek: apakah aku membagikan sumber/bantuan yang kupunya? apakah aku menawarkan bantuan saat bagianku selesai? apakah aku menepati bagianku? apa satu hal yang akan kuperbaiki?","Menilai anggota lain yang kurang berbagi kepada guru dan tim, tanpa bertanya pada dirimu apakah kamu sendiri sudah cukup berbagi, lalu menganggap itu bukan urusanmu lagi"],answer:1,explain:"Menilai kontribusi & sikap berbagimu sendiri (bukan hanya orang lain) mempercepat kamu jadi rekan tim yang dipercaya.",hint:"Evaluasi sikap berbagimu sendiri, atau menilai orang lain / tak pernah?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti berbagi tugas & sumber daya:",options:["Koordinator menunjuk tugas kepada tiap anggota tanpa diskusi, lalu tiap orang mengurus bagiannya sendiri dan menyimpan alat serta informasi yang ia punya, sehingga hasilnya sulit digabung, dan masalah dibahas hanya bila sudah terlambat","Satu orang yang paling mampu mengerjakan semua bagian supaya hasilnya seragam dan cepat, sedangkan anggota lain menunggu hasilnya lalu mencantumkan nama mereka, dan masalah dibahas bila sudah terlanjur di akhir proyek","Pecah pekerjaan & daftar bersama, bagi adil (beban sebanding + cocok kekuatan + ketersediaan) lewat proses transparan, tuliskan + konfirmasi, berbagi info/alat/bantuan secara terbuka, tenggat bertahap, & seimbangkan ulang saat perlu"],answer:2,explain:"Ringkasan: daftar & pecah → bagi adil & transparan → tulis & konfirmasi → berbagi sumber & bantuan terbuka → tenggat bertahap → seimbangkan ulang.",hint:"Daftar & pecah, bagi adil & transparan, tulis, berbagi terbuka, tenggat bertahap, seimbangkan ulang — rangkai."},
{n:98,type:"tf",micro:"Refleksi: berbagi = tim, bukan kumpulan individu",q:"Benar atau Salah: Yang membedakan sebuah 'tim' dari sekadar 'beberapa orang yang mengerjakan tugas berdekatan' adalah adanya pembagian yang adil & berbagi sumber daya, informasi, serta bantuan secara nyata.",answer:true,explain:"Tanpa berbagi, orang-orang itu hanya bekerja paralel. Dengan berbagi, mereka menjadi tim yang hasilnya melebihi jumlah usaha masing-masing.",hint:"Berbagi membedakan tim dari kumpulan individu, atau tidak?"},
{n:99,type:"mcq",micro:"Kasus: memulai kebiasaan berbagi yang baik",q:"Cara termudah mulai jadi anggota tim yang lebih baik dalam berbagi minggu ini:",options:["Pilih satu tindakan: bagikan satu sumber berguna ke tim, atau tawarkan bantuan ke satu anggota saat bagianmu selesai, atau usulkan mendaftar & menimbang beban bersama sebelum membagi","Menunggu sampai ada tim yang lebih adil dan terorganisasi baru mulai belajar berbagi, karena di tim yang sekarang tidak ada gunanya mencoba, lalu berharap masalahnya selesai sendiri tanpa perlu ada yang bicara","Berharap orang lain yang lebih dulu memulai berbagi sumber & bantuan, lalu baru kamu menirunya setelah yakin kamu tidak akan dirugikan, walaupun hal itu membuat suasana dan kerja sama tim jadi makin sulit"],answer:0,explain:"Budaya berbagi sering dimulai dari satu anggota yang konsisten melakukan satu hal kecil.",hint:"Lakukan satu tindakan berbagi konsisten, atau menunggu / berharap?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi berbagi tugas",q:"Tulis 'aturan pribadi tentang berbagi tugas & sumber daya dalam tim' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: daftar & perkirakan beban bersama di awal, dukung pembagian sebanding + cocok kekuatan + mempertimbangkan waktu, bagikan sumber/alat/keterampilan terbuka, tawarkan/minta bantuan untuk menyeimbangkan beban, selesaikan bagian + kabari kendala, bagikan draf lebih awal, batas berbagi yang sehat & timbal balik, akui kontribusi semua.",hint:"Ambil satu pelajaran tiap fase — daftar & timbang beban, pembagian sebanding, berbagi sumber terbuka, saling bantu menyeimbangkan, tanggung jawab pada bagian, draf awal, batas & timbal balik, akui kontribusi — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Di awal proyek, aku ikut memastikan tim mendaftar semua pekerjaan & memperkirakan bebannya bersama sebelum membagi — karena pembagian adil butuh peta lengkap & perkiraan beban. (2) Aku mendukung pembagian yang beban tiap orang sebanding, cocok kekuatan, dan mempertimbangkan ketersediaan waktu — bukan 'siapa cepat dia dapat' atau menumpuk ke yang rajin. (3) Aku membagikan referensi, template, alat, dan keterampilan yang kupunya ke seluruh tim di kanal bersama — karena sumber yang dibagikan berlipat guna & tim yang berbagi lebih kuat. (4) Kalau bagianku selesai lebih dulu, aku menawarkan bantuan; kalau aku kewalahan, aku minta bantuan lebih awal — karena beban diseimbangkan sepanjang proyek. (5) Aku menyelesaikan bagianku sesuai standar & tenggat dan mengabari tim bila ada risiko molor — karena berbagi tugas berarti berbagi tanggung jawab. (6) Aku membagikan draf bagianku beberapa hari sebelum tenggat untuk dicek bersama — karena itu menghasilkan proyek yang lebih nyambung. (7) Aku menetapkan batas berbagi sumber daya pribadi yang aku nyaman, dan berbagi yang sehat itu timbal balik — supaya aku membantu tanpa dieksploitasi. (8) Saat presentasi/penilaian, aku menyebut kontribusi tiap anggota dengan jujur & adil."},
];
